WITH base AS (SELECT *, DATEDIFF(CURRENT_DATE(), event_time) AS days_since_event_time FROM web_events WHERE page IS NOT NULL), with_prev AS (SELECT *, LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) AS prev_event_time FROM base), with_gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '7' DAY THEN 1 ELSE 0 END AS is_new_session FROM with_prev), islands AS (SELECT id, session_id, event_type, page, event_time, duration_sec, days_since_event_time, SUM(is_new_session) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT session_no, CASE WHEN duration_sec >= 514 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, DATE_TRUNC('MONTH', event_time) AS activity_month, COUNT(CASE WHEN page = '/checkout' THEN 1 END) AS checkout_count, ROUND(SUM(duration_sec) / NULLIF(COUNT(CASE WHEN page = '/product' THEN 1 END), 0), 2) AS duration_sec_per_product, MAX(event_time) AS last_seen FROM islands GROUP BY GROUPING SETS ((session_no, CASE WHEN duration_sec >= 514 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('MONTH', event_time)), (session_no, CASE WHEN duration_sec >= 514 THEN 'LARGE' ELSE 'SMALL' END), ())
